/**
 * UI generated by the model.
 *
 * The model calls `show_ui` with a declarative document made of blocks from a closed catalogue (table,
 * list, facts, chart, choices, form). The engine validates and normalises it (`validateDocument`) before
 * anything shows it; the result's `details.document` is that normalised document, the only form a client
 * renders. The graphical window builds each block from its own components; the terminal shows the full
 * text equivalent. Nothing from the model is executed or interpreted: no HTML,
 * Markdown, style, script or URL is part of the catalogue, and every string is shown as text.
 *
 * A choice or a form is the user's answer, and nothing more: `ui_submit` (RPC) builds the message from the
 * validated document and the user's values (`answerMessage`), and sends it as a plain user message (no
 * command, template or skill expansion, and a fixed opening that is never a command). It gains no
 * privilege: what the model does with it goes through the permission gate like any other turn. Only the
 * latest document of the conversation can be answered, once, and not while a turn runs.
 *
 * While the model writes the call, RPC clients get `ui_preview {toolCallId, document}` each time a block is
 * complete (`createUiPreviews`): the wire's deltas carry no parsed arguments, and the preview is validated
 * as the final document is, so a client never draws anything the engine has not checked.
 */

import { StringEnum } from "@earendil-works/pi-ai";
import { type Component, Text, visibleWidth, wrapTextWithAnsi } from "@earendil-works/pi-tui";
import { Type } from "typebox";
import type { AgentSession, AgentSessionEvent } from "../core/agent-session.ts";
import type { ExtensionAPI } from "../core/extensions/types.ts";
import { fill, t } from "./i18n/index.ts";
import { own } from "./own.ts";

export const SHOW_UI_TOOL = "show_ui";
export const DOCUMENT_VERSION = 1;

const LIMITS = {
	title: 120,
	blocks: 12,
	label: 80,
	text: 500,
	columns: 12,
	rows: 200,
	items: 100,
	labels: 50,
	series: 6,
	options: 8,
	fields: 10,
	fieldOptions: 20,
};

export type Cell = string | number;

export type Block =
	| { type: "table"; title?: string; columns: string[]; rows: Cell[][] }
	| { type: "list"; title?: string; ordered: boolean; items: string[] }
	| { type: "facts"; title?: string; items: { label: string; value: string }[] }
	| {
			type: "chart";
			title?: string;
			kind: "bar" | "line";
			labels: string[];
			series: { name: string; values: number[] }[];
			unit?: string;
	  }
	| { type: "choices"; title?: string; options: { label: string; reply: string }[] }
	| { type: "form"; title?: string; fields: Field[]; submit: string };

export interface Field {
	name: string;
	label: string;
	kind: "text" | "number" | "select" | "toggle";
	options?: string[];
	required: boolean;
}

export interface UiDocument {
	version: number;
	title?: string;
	blocks: Block[];
}

export interface ShowUiDetails {
	document: UiDocument;
}

class InvalidDocument extends Error {}

function fail(message: string): never {
	throw new InvalidDocument(message);
}

function record(value: unknown, where: string): Record<string, unknown> {
	if (typeof value !== "object" || value === null || Array.isArray(value)) fail(`${where} must be an object`);
	return value as Record<string, unknown>;
}

function list(value: unknown, where: string, min: number, max: number): unknown[] {
	if (!Array.isArray(value)) fail(`${where} must be an array`);
	if (value.length < min) fail(`${where} needs at least ${min} entr${min === 1 ? "y" : "ies"}`);
	if (value.length > max) fail(`${where} has ${value.length} entries; at most ${max}`);
	return value;
}

/** One line of text: control characters and line breaks become spaces, runs of spaces one. */
function text(value: unknown, where: string, max: number): string {
	if (typeof value === "number" && Number.isFinite(value)) value = String(value);
	if (typeof value !== "string") fail(`${where} must be a string`);
	const clean = value
		.replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029]/g, " ")
		.replace(/\s+/g, " ")
		.trim();
	if (!clean) fail(`${where} is empty`);
	return clean.length > max ? `${clean.slice(0, max - 1)}…` : clean;
}

function optionalText(value: unknown, where: string, max: number): string | undefined {
	return value === undefined || value === null || value === "" ? undefined : text(value, where, max);
}

function cell(value: unknown, where: string): Cell {
	if (typeof value === "number") {
		if (!Number.isFinite(value)) fail(`${where} must be a finite number`);
		return value;
	}
	if (value === null || value === undefined || value === "") return "";
	return text(value, where, LIMITS.text);
}

function block(raw: unknown, where: string): Block {
	const input = record(raw, where);
	const title = optionalText(input.title, `${where}.title`, LIMITS.title);
	const base = title ? { title } : {};
	switch (input.type) {
		case "table": {
			const columns = list(input.columns, `${where}.columns`, 1, LIMITS.columns).map((c, i) =>
				text(c, `${where}.columns[${i}]`, LIMITS.label),
			);
			const rows = list(input.rows, `${where}.rows`, 1, LIMITS.rows).map((row, r) => {
				const cells = list(row, `${where}.rows[${r}]`, 1, columns.length).map((c, i) =>
					cell(c, `${where}.rows[${r}][${i}]`),
				);
				return [...cells, ...Array<Cell>(columns.length - cells.length).fill("")];
			});
			return { type: "table", ...base, columns, rows };
		}
		case "list":
			return {
				type: "list",
				...base,
				ordered: input.ordered === true,
				items: list(input.items, `${where}.items`, 1, LIMITS.items).map((item, i) =>
					text(item, `${where}.items[${i}]`, LIMITS.text),
				),
			};
		case "facts":
			return {
				type: "facts",
				...base,
				items: list(input.items, `${where}.items`, 1, LIMITS.items).map((raw, i) => {
					const item = record(raw, `${where}.items[${i}]`);
					return {
						label: text(item.label, `${where}.items[${i}].label`, LIMITS.label),
						value: text(item.value, `${where}.items[${i}].value`, LIMITS.text),
					};
				}),
			};
		case "chart": {
			const kind =
				input.kind === "line" ? "line" : input.kind === "bar" || input.kind === undefined ? "bar" : undefined;
			if (!kind) fail(`${where}.kind must be "bar" or "line"`);
			const labels = list(input.labels, `${where}.labels`, 1, LIMITS.labels).map((l, i) =>
				text(l, `${where}.labels[${i}]`, LIMITS.label),
			);
			const series = list(input.series, `${where}.series`, 1, LIMITS.series).map((raw, s) => {
				const one = record(raw, `${where}.series[${s}]`);
				const values = list(one.values, `${where}.series[${s}].values`, labels.length, labels.length).map(
					(v, i) => {
						if (typeof v !== "number" || !Number.isFinite(v))
							fail(`${where}.series[${s}].values[${i}] must be a number`);
						return v;
					},
				);
				return { name: text(one.name ?? `Series ${s + 1}`, `${where}.series[${s}].name`, LIMITS.label), values };
			});
			const unit = optionalText(input.unit, `${where}.unit`, 16);
			return { type: "chart", ...base, kind, labels, series, ...(unit ? { unit } : {}) };
		}
		case "choices":
			return {
				type: "choices",
				...base,
				options: list(input.options, `${where}.options`, 1, LIMITS.options).map((raw, i) => {
					const option = typeof raw === "string" ? { label: raw } : record(raw, `${where}.options[${i}]`);
					const label = text(option.label, `${where}.options[${i}].label`, LIMITS.label);
					return {
						label,
						reply: optionalText(option.reply, `${where}.options[${i}].reply`, LIMITS.text) ?? label,
					};
				}),
			};
		case "form": {
			const names = new Set<string>();
			const fields = list(input.fields, `${where}.fields`, 1, LIMITS.fields).map((raw, i): Field => {
				const field = record(raw, `${where}.fields[${i}]`);
				const label = text(field.label, `${where}.fields[${i}].label`, LIMITS.label);
				const name = optionalText(field.name, `${where}.fields[${i}].name`, LIMITS.label) ?? label;
				if (names.has(name)) fail(`${where}.fields[${i}].name "${name}" is used twice`);
				names.add(name);
				const kind = field.kind ?? "text";
				if (kind !== "text" && kind !== "number" && kind !== "select" && kind !== "toggle")
					fail(`${where}.fields[${i}].kind must be text, number, select or toggle`);
				const options =
					kind === "select"
						? list(field.options, `${where}.fields[${i}].options`, 1, LIMITS.fieldOptions).map((o, j) =>
								text(o, `${where}.fields[${i}].options[${j}]`, LIMITS.label),
							)
						: undefined;
				return { name, label, kind, ...(options ? { options } : {}), required: field.required === true };
			});
			return {
				type: "form",
				...base,
				fields,
				submit: optionalText(input.submit, `${where}.submit`, LIMITS.label) ?? "Send",
			};
		}
		default:
			return fail(`${where}.type must be one of table, list, facts, chart, choices, form`);
	}
}

/** The normalised document, or why it cannot be shown. */
export function validateDocument(raw: unknown): { document: UiDocument } | { error: string } {
	try {
		const input = record(raw, "the document");
		const blocks = list(input.blocks, "blocks", 1, LIMITS.blocks).map((b, i) => block(b, `blocks[${i}]`));
		if (blocks.filter((b) => b.type === "choices" || b.type === "form").length > 1)
			fail("at most one choices or form block per document: the user answers one question at a time");
		const title = optionalText(input.title, "title", LIMITS.title);
		return { document: { version: DOCUMENT_VERSION, ...(title ? { title } : {}), blocks } };
	} catch (error) {
		if (error instanceof InvalidDocument) return { error: error.message };
		throw error;
	}
}

// ---------------------------------------------------------------------------------------------------
// The text equivalent (the terminal)

function number(value: number): string {
	return Number.isInteger(value) ? String(value) : String(Number(value.toPrecision(6)));
}

type Style = { bold(text: string): string; muted(text: string): string };

/** Columns when they fit `width`; otherwise one record per row ("Column: value", wrapped), so no cell is cut. */
function tableLines(header: string[], rows: string[][], width: number, style: Style): string[] {
	const gap = "  ";
	// A loop, not Math.max(...rows): a spread of a model-sized row count passes the argument limit.
	const widths = header.map((h, i) => {
		let widest = visibleWidth(h);
		for (const row of rows) widest = Math.max(widest, visibleWidth(row[i] ?? ""));
		return widest;
	});
	if (widths.reduce((a, b) => a + b, 0) + gap.length * (header.length - 1) <= width) {
		const line = (cells: string[]) =>
			cells
				.map((cell, i) => cell + " ".repeat(widths[i] - visibleWidth(cell)))
				.join(gap)
				.trimEnd();
		return [style.bold(line(header)), ...rows.map(line)];
	}
	return rows.flatMap((row, r) => [
		...(r > 0 ? [""] : []),
		...header.flatMap((h, i) => wrapTextWithAnsi(`${style.muted(`${h}:`)} ${row[i] ?? ""}`, Math.max(1, width))),
	]);
}

/**
 * The whole document as lines of plain text, everything it shows included. Nothing is parsed as
 * Markdown: the model's strings are shown exactly as written.
 */
export function documentLines(document: UiDocument, width: number, style: Style): string[] {
	const out: string[] = [];
	// fork: lines are appended one by one; a narrow table can make millions.
	const add = (lines: string[]) => {
		for (const line of lines) out.push(line);
	};
	const wrap = (text: string, indent = "") =>
		wrapTextWithAnsi(text, Math.max(1, width - visibleWidth(indent))).map((line, i) =>
			i === 0 ? indent + line : " ".repeat(visibleWidth(indent)) + line,
		);
	if (document.title) {
		add(wrap(style.bold(document.title)));
		out.push("");
	}
	for (const b of document.blocks) {
		if (b.title) add(wrap(style.bold(b.title)));
		switch (b.type) {
			case "table":
				add(
					tableLines(
						b.columns,
						b.rows.map((row) => row.map((c) => (typeof c === "number" ? number(c) : c))),
						width,
						style,
					),
				);
				break;
			case "list":
				b.items.forEach((item, i) => {
					add(wrap(item, b.ordered ? `${i + 1}. ` : "- "));
				});
				break;
			case "facts":
				for (const item of b.items) add(wrap(`${style.muted(`${item.label}:`)} ${item.value}`));
				break;
			case "chart": {
				const unit = b.unit ? ` ${b.unit}` : "";
				add(
					tableLines(
						[t("Label"), ...b.series.map((one) => one.name)],
						b.labels.map((label, i) => [label, ...b.series.map((one) => `${number(one.values[i])}${unit}`)]),
						width,
						style,
					),
				);
				break;
			}
			case "choices":
				add(wrap(style.muted(t("Options (answer with one of them):"))));
				b.options.forEach((option, i) => {
					add(wrap(option.label, `${i + 1}. `));
				});
				break;
			case "form":
				add(wrap(style.muted(t("Questions (answer them in a message):"))));
				for (const field of b.fields) {
					const choices = field.options
						? ` (${field.options.join(", ")})`
						: field.kind === "toggle"
							? ` (${t("yes")}/${t("no")})`
							: "";
					add(wrap(`${field.label}${choices}${field.required ? " *" : ""}`, "- "));
				}
				break;
		}
		out.push("");
	}
	while (out.length && out[out.length - 1] === "") out.pop();
	return out;
}

function describe(b: Block): string {
	switch (b.type) {
		case "table":
			return `table ${b.columns.length}×${b.rows.length}`;
		case "list":
			return `list of ${b.items.length}`;
		case "facts":
			return `${b.items.length} facts`;
		case "chart":
			return `${b.kind} chart of ${b.labels.length} points`;
		case "choices":
			return `${b.options.length} choices`;
		case "form":
			return `form of ${b.fields.length} fields`;
	}
}

function summary(document: UiDocument): string {
	const parts = document.blocks.map(describe);
	const question = document.blocks.some((b) => b.type === "choices" || b.type === "form");
	return `Shown to the user: ${parts.join(", ")}.${question ? " Their answer, if they give one, arrives as their next message; end your turn now." : ""}`;
}

// ---------------------------------------------------------------------------------------------------
// The user's answer

export type Answer = { choice: number } | { values: Record<string, unknown> };

/** The message an answer sends: built here from the validated document, never taken from the client as is. */
export function answerMessage(document: UiDocument, answer: Answer): { message: string } | { error: string } {
	const question = document.blocks.find((b) => b.type === "choices" || b.type === "form");
	if (!question) return { error: "This UI asks nothing" };
	const heading = question.title ?? document.title;
	const opening = heading ? fill("Answer to “{0}”:", heading) : t("Answer:");
	if (question.type === "choices") {
		if (!("choice" in answer) || !Number.isInteger(answer.choice) || !question.options[answer.choice])
			return { error: "Unknown choice" };
		return { message: `${opening} ${question.options[answer.choice].reply}` };
	}
	if (!("values" in answer) || typeof answer.values !== "object" || answer.values === null)
		return { error: "No values" };
	const lines: string[] = [];
	for (const field of question.fields) {
		// fork: a field named `__proto__` or `constructor` reads its own answer.
		const raw = own(answer.values, field.name);
		let value: string | undefined;
		if (field.kind === "toggle") value = raw === true ? t("yes") : t("no");
		else if (field.kind === "number") {
			const n = typeof raw === "number" ? raw : typeof raw === "string" && raw.trim() ? Number(raw) : undefined;
			if (n !== undefined && !Number.isFinite(n)) return { error: fill("{0}: not a number", field.label) };
			// fork: the number as the user gave it, not rounded for a chart.
			value = n === undefined ? undefined : typeof raw === "string" ? raw.trim() : String(n);
		} else if (field.kind === "select") {
			if (raw !== undefined && raw !== "" && !field.options?.includes(String(raw)))
				return { error: fill("{0}: not one of the options", field.label) };
			value = raw === undefined || raw === "" ? undefined : String(raw);
		} else if (raw !== undefined && raw !== null && raw !== "") {
			if (typeof raw !== "string") return { error: fill("{0}: not text", field.label) };
			value = raw.replace(/\r\n?/g, "\n").trim().slice(0, 2000) || undefined;
		}
		if (value === undefined && field.required) return { error: fill("{0} is required", field.label) };
		lines.push(`- ${field.label}: ${value ?? "—"}`);
	}
	return { message: `${opening}\n${lines.join("\n")}` };
}

interface Entry {
	type: string;
	message?: { role?: string; toolCallId?: string; toolName?: string; details?: unknown };
}

/**
 * The document of `toolCallId` when it can still be answered: the latest `show_ui` result of the current
 * branch, with no user message after it.
 */
export function answerable(entries: readonly Entry[], toolCallId: string): UiDocument | undefined {
	for (let i = entries.length - 1; i >= 0; i--) {
		const message = entries[i].type === "message" ? entries[i].message : undefined;
		if (!message) continue;
		if (message.role === "user") return undefined;
		if (message.role === "toolResult" && message.toolName === SHOW_UI_TOOL) {
			if (message.toolCallId !== toolCallId) return undefined;
			const details = message.details as Partial<ShowUiDetails> | undefined;
			// Validated again: the session file may have been edited.
			const checked = details?.document ? validateDocument(details.document) : undefined;
			return checked && "document" in checked ? checked.document : undefined;
		}
	}
	return undefined;
}

/**
 * Sessions with an answer on its way. Until its prompt has started, neither the user message that closes
 * the question nor the busy state is there yet: a second click then must not send a second answer. (Not a
 * set of answered call ids: some providers reuse ids from one reply to the next.)
 */
const answering = new WeakSet<AgentSession>();

/**
 * `ui_submit {toolCallId, choice | values}` over RPC: the answer, sent as a plain user message. Resolves
 * as the RPC `prompt` command answers, once the prompt's preflight has accepted it.
 */
export function submitAnswer(
	session: AgentSession,
	toolCallId: unknown,
	answer: Answer,
): Promise<{ disposition: string }> {
	if (session.isStreaming) return Promise.reject(new Error(t("Wait for the current reply to end")));
	const document =
		typeof toolCallId === "string" && !answering.has(session)
			? answerable(session.sessionManager.getBranch(), toolCallId)
			: undefined;
	if (!document) return Promise.reject(new Error(t("This question can no longer be answered")));
	const built = answerMessage(document, answer);
	if ("error" in built) return Promise.reject(new Error(built.error));
	answering.add(session);
	return new Promise((resolve, reject) => {
		void session
			.prompt(built.message, {
				expandPromptTemplates: false,
				source: "rpc",
				preflightResult: (disposition) => {
					answering.delete(session);
					resolve({ disposition });
				},
			})
			.catch((error: unknown) => {
				if (!answering.delete(session)) return;
				reject(error instanceof Error ? error : new Error(String(error)));
			});
	});
}

/**
 * Over RPC, the document of a `show_ui` call while the model writes it: an event each time one more block is
 * complete (the next one has started), with the complete blocks validated. At most one per block.
 */
export function createUiPreviews(): (event: AgentSessionEvent) => object | undefined {
	const shown = new Map<string, number>();
	return (event) => {
		if (event.type === "agent_end") shown.clear();
		if (event.type !== "message_update" || event.assistantMessageEvent.type !== "toolcall_delta") return undefined;
		const part =
			event.message.role === "assistant"
				? event.message.content[event.assistantMessageEvent.contentIndex]
				: undefined;
		if (part?.type !== "toolCall" || part.name !== SHOW_UI_TOOL) return undefined;
		const blocks = Array.isArray(part.arguments.blocks) ? part.arguments.blocks : [];
		const complete = blocks.length - 1;
		if (complete <= (shown.get(part.id) ?? 0)) return undefined;
		const checked = validateDocument({ title: part.arguments.title, blocks: blocks.slice(0, complete) });
		if (!("document" in checked)) return undefined;
		shown.set(part.id, complete);
		return { type: "ui_preview", toolCallId: part.id, document: checked.document };
	};
}

// ---------------------------------------------------------------------------------------------------
// The tool

const cellSchema = Type.Union([Type.String(), Type.Number()]);

/**
 * fork.10.5 ("show_ui n'est toujours pas l'outil le plus simple à utiliser pour les modèles"):
 * one example of each block, in the description and in the error of a refused document, so a model sees the
 * fields each type takes rather than inferring them from the schema's optional properties.
 */
const BLOCK_SHAPES = [
	'table: {"type":"table","columns":["File","Lines"],"rows":[["a.ts",120],["b.ts",80]]}',
	'list: {"type":"list","items":["First","Second"],"ordered":true}',
	'facts: {"type":"facts","items":[{"label":"Size","value":"2 MB"},{"label":"Files","value":14}]}',
	'chart: {"type":"chart","kind":"bar","labels":["Mon","Tue"],"series":[{"name":"Runs","values":[3,5]}],"unit":"s"}',
	'choices: {"type":"choices","options":["Keep it",{"label":"Remove it","reply":"Remove the file"}]}',
	'form: {"type":"form","fields":[{"label":"Name","kind":"text","required":true},{"label":"Size","kind":"select","options":["S","M"]}],"submit":"Create"}',
];
const BLOCK_SHAPES_TEXT = `Each block, by type:\n${BLOCK_SHAPES.map((shape) => `- ${shape}`).join("\n")}`;

export default function generatedUi(pi: ExtensionAPI) {
	pi.registerTool<ReturnType<typeof parametersSchema>, ShowUiDetails>({
		name: SHOW_UI_TOOL,
		label: "Show UI",
		// Shows what the model already wrote; reads, writes and runs nothing.
		permissions: ["none"],
		description: `Show structured content to the user as interface blocks: tables, lists, key facts, bar or line charts, a set of choices to click, or a short form. The user's window draws them; a terminal shows the same content as text. Every string is shown as plain text (no Markdown, HTML or links). A choices or form block asks the user: their answer arrives as their next message, so end your turn after showing one. Arguments: {"title"?: string, "blocks": [block, ...]}. ${BLOCK_SHAPES_TEXT}`,
		promptSnippet: "Show tables, charts, choices or a short form to the user",
		promptGuidelines: [
			"Use show_ui for data that reads better as a table or chart, or to offer the user a few choices or a short form; keep prose and code in your reply.",
		],
		parameters: parametersSchema(),
		async execute(_id, params) {
			const checked = validateDocument(params);
			if ("error" in checked)
				throw new Error(`Invalid UI document: ${checked.error}. Nothing was shown.\n${BLOCK_SHAPES_TEXT}`);
			return {
				content: [{ type: "text", text: summary(checked.document) }],
				details: { document: checked.document },
			};
		},
		// While the model writes the document: its title only, not the arguments.
		renderCall(args, theme) {
			const title = typeof args.title === "string" && args.title.trim() ? ` ${args.title.trim()}` : "";
			return new Text(`${theme.fg("toolTitle", t("Interface"))}${theme.fg("muted", title)}`, 0, 0);
		},
		renderResult(result, _options, theme): Component {
			const document = result.details?.document;
			const style = { bold: (text: string) => theme.bold(text), muted: (text: string) => theme.fg("muted", text) };
			return { render: (width) => (document ? documentLines(document, width, style) : []), invalidate() {} };
		},
	});
}

function parametersSchema() {
	return Type.Object({
		title: Type.Optional(Type.String({ description: "Title above the blocks" })),
		blocks: Type.Array(
			Type.Object({
				type: StringEnum(["table", "list", "facts", "chart", "choices", "form"] as const),
				title: Type.Optional(Type.String()),
				columns: Type.Optional(Type.Array(Type.String(), { description: "table: column headers" })),
				rows: Type.Optional(
					Type.Array(Type.Array(cellSchema), { description: "table: rows of cells, in column order" }),
				),
				items: Type.Optional(
					Type.Array(Type.Union([Type.String(), Type.Object({ label: Type.String(), value: cellSchema })]), {
						description: "list: strings; facts: {label, value}",
					}),
				),
				ordered: Type.Optional(Type.Boolean({ description: "list: numbered" })),
				kind: Type.Optional(StringEnum(["bar", "line"] as const, { description: "chart" })),
				// Before labels: a grammar-constrained model (llama.cpp) keeps the schema's property order, and
				// Qwen, which writes the unit first, then could never write labels or series (6 charts in 7 without them).
				unit: Type.Optional(Type.String({ description: "chart: unit of the values" })),
				labels: Type.Optional(Type.Array(Type.String(), { description: "chart (required): x-axis labels" })),
				series: Type.Optional(
					Type.Array(Type.Object({ name: Type.String(), values: Type.Array(Type.Number()) }), {
						description: "chart (required): one value per label",
					}),
				),
				options: Type.Optional(
					Type.Array(
						Type.Union([
							Type.String(),
							Type.Object({ label: Type.String(), reply: Type.Optional(Type.String()) }),
						]),
						{
							description: "choices: what the user can click; reply is the message it sends (default: label)",
						},
					),
				),
				fields: Type.Optional(
					Type.Array(
						Type.Object({
							label: Type.String(),
							name: Type.Optional(Type.String()),
							kind: Type.Optional(StringEnum(["text", "number", "select", "toggle"] as const)),
							options: Type.Optional(Type.Array(Type.String(), { description: "select: the options" })),
							required: Type.Optional(Type.Boolean()),
						}),
						{ description: "form: the questions" },
					),
				),
				submit: Type.Optional(Type.String({ description: "form: label of its send button" })),
			}),
			{ description: "The blocks, in order (at most 12; at most one choices or form block)" },
		),
	});
}
